/* Quantify Core — prototipo local sin servicios externos ni dependencias. */
(() => {
  'use strict';
  const {screens,rules,date:today} = window.QC;
  const $ = (q,root=document)=>root.querySelector(q);
  const $$ = (q,root=document)=>[...root.querySelectorAll(q)];
  const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const normalize = value=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase().replace(/\s+/g,' ');
  const key='quantify-practica07-v1';
  const dayLabels=['L','M','X','J','V','S','D'];
  const dateAt=offset=>{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
  const weekday=day=>(new Date(day+'T12:00:00').getDay()+6)%7;
  const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',chart:'M4 20V10m8 10V4m8 16v-7M2 21h20',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1ZM12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5ZM10 21h4',arrow:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',book:'M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4ZM12 6v15',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M18 8a3 3 0 0 1 0 6m1 3a4 4 0 0 1 3 4',list:'M8 5h13M8 12h13M8 19h13M3 5h.1M3 12h.1M3 19h.1',clock:'M12 8v5l3 2M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',lock:'M5 10h14v11H5ZM8 10V6a4 4 0 0 1 8 0v4M12 14v3',archive:'M3 3h18v5H3ZM5 8v13h14V8M9 12h6',leaf:'M20 3C9 2 3 7 5 14s15 6 15-11ZM4 21 15 10'};
  const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
  const go=(id,label,cls='primary',extra='')=>`<button type="button" class="${cls}" data-go="${id}" ${extra}>${label}</button>`;
  const action=(name,label,cls='secondary',extra='')=>`<button type="button" class="${cls}" data-action="${name}" ${extra}>${label}</button>`;
  const logo=()=>'<span class="logo-crop"><img src="../quantifyLogo.jpeg" alt="Quantify Core"></span>';
  function seed(){
    const habits=[
      {id:'h1',name:'Lectura consciente',category:'Estudio',target:20,unit:'min',days:[0,1,2,3,4,5,6],color:'#1E54C9',reminder:{enabled:true,time:'08:00',days:[0,1,2,3,4,5,6]},logs:{}},
      {id:'h2',name:'Beber agua',category:'Salud',target:2000,unit:'ml',days:[0,1,2,3,4,5,6],color:'#269b9c',reminder:{enabled:true,time:'10:00',days:[0,1,2,3,4,5,6]},logs:{}},
      {id:'h3',name:'Enfoque profundo',category:'Productividad',target:45,unit:'min',days:[0,1,2,3,4],color:'#8c7bd1',reminder:{enabled:false,time:'16:00',days:[0,1,2,3,4]},logs:{}},
      {id:'h4',name:'Pausa consciente',category:'Bienestar',target:10,unit:'min',days:[0,1,2,3,4,5,6],color:'#d69851',reminder:{enabled:false,time:'18:00',days:[0,1,2,3,4,5,6]},logs:{}}
    ];
    habits.forEach((h,j)=>{for(let i=-27;i<0;i++){const d=dateAt(i);if(h.days.includes(weekday(d)))h.logs[d]=((Math.abs(i)+j)%6===0)?0:h.target;}});
    habits[0].logs[today]=20;habits[1].logs[today]=500;habits[2].logs[today]=0;habits[3].logs[today]=10;
    return {version:1,habits,profile:{name:'Alex Morgan',consent:true,push:true,summary:true},config:{confidence:80,cap:2},recommendations:[{id:'r1',templateId:'t2',name:'Movilidad de escritorio',category:'Salud',target:5,unit:'min',confidence:92,reason:'En los registros de ejemplo, las sesiones de enfoque son largas. Una pausa breve ofrece un descanso entre bloques.',active:true},{id:'r2',templateId:'t3',name:'Planificar el siguiente día',category:'Productividad',target:10,unit:'min',confidence:86,reason:'Tu rutina de ejemplo tiene mayor constancia al final del día. Preparar el siguiente bloque puede ayudarte a mantenerla.',active:true}],dismissed:{},templates:[{id:'t1',name:'Lectura consciente',category:'Estudio',target:20,unit:'min',active:true},{id:'t2',name:'Movilidad de escritorio',category:'Salud',target:5,unit:'min',active:true},{id:'t3',name:'Planificar el siguiente día',category:'Productividad',target:10,unit:'min',active:true}],accounts:[{id:'QC-1042',active:true},{id:'QC-1088',active:true},{id:'QC-1120',active:false},{id:'ADM-001',active:true,self:true}],audit:[],readNotices:[]};
  }
  let db;
  try{db=JSON.parse(localStorage.getItem(key));if(!db||db.version!==1||!Array.isArray(db.habits)||!db.profile||!db.config||!Array.isArray(db.templates)||!Array.isArray(db.recommendations)||!Array.isArray(db.accounts)||!Array.isArray(db.audit))db=seed();}catch{db=seed();}
  const view={role:'usuario',screen:'U01',platform:'mobile',selected:db.habits.find(h=>!h.archived)?.id||db.habits[0]?.id,editId:null,recommendation:null,template:'t1',account:'QC-1042',verify:'register',filter:'Todos',period:7,auditFilter:'Todas',trail:[]};
  let toastTimer,confirmAction,registered=null,verifiedRecovery=false,recoveryEmail='',sessionPassword='Demo2026!';
  const habit=()=>db.habits.find(h=>h.id===view.selected)||db.habits[0];
  const activeHabits=()=>db.habits.filter(h=>!h.archived);
  const scheduled=(h,day=today)=>(h.daysByDate?.[day]||h.days).includes(weekday(day));
  const amount=(h,day=today)=>h.logs[day]||0;
  const complete=(h,day=today)=>amount(h,day)>=(h.targetByDate?.[day]||h.target);
  const todayHabits=()=>activeHabits().filter(h=>scheduled(h));
  function streak(h){let count=0;const end=complete(h)?0:-1;for(let i=end;i>=-365;i--){const day=dateAt(i);if(!scheduled(h,day))continue;if(complete(h,day))count++;else break;}return count;}
  const section=(title,sub='')=>`<div class="section-title"><h3>${title}</h3>${sub?`<small>${sub}</small>`:''}</div>`;
  const heading=(title,subtitle,kicker='QUANTIFY CORE',pill='')=>`<div class="screen-kicker"><span>${kicker}</span>${pill}</div><h1 class="screen-heading">${title}</h1><p class="screen-subtitle">${subtitle}</p>`;
  const note=(text,cls='')=>`<div class="note ${cls}">${text}</div>`;
  const metric=(label,value,sub)=>`<div class="card metric"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`;
  const field=(label,name,type='text',value='',extra='')=>`<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;
  const options=(values,current)=>values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');
  const select=(label,name,values,current)=>`<label class="field">${label}<select name="${name}">${options(values,current)}</select></label>`;
  const error=()=>'<div class="form-error" role="alert"></div>';
  const daysInput=(chosen,allowed=[0,1,2,3,4,5,6])=>`<div class="days" role="group" aria-label="Días programados">${dayLabels.map((d,i)=>`<label class="day-choice"><input type="checkbox" name="days" value="${i}" aria-label="${['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'][i]}" ${chosen.includes(i)?'checked':''} ${!allowed.includes(i)?'disabled':''}><span>${d}</span></label>`).join('')}</div>`;
  const toggle=(name,label,description,checked)=>`<label class="toggle-line"><span><strong>${label}</strong><small>${description}</small></span><input type="checkbox" name="${name}" ${checked?'checked':''}></label>`;
  function save(){try{localStorage.setItem(key,JSON.stringify(db));}catch{toast('El navegador no permite guardar; los cambios durarán durante esta visita.');}}
  function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
  function log(entity,actionName,reason){db.audit.unshift({id:crypto.randomUUID?.()||String(Date.now()),at:new Date().toISOString(),entity,action:actionName,reason,actor:'ADM-001'});save();}
  function routeFromHash(){const [role,id]=decodeURI(location.hash.slice(1)).split('/');if(screens[role]?.some(s=>s.id===id)){view.role=role;view.screen=id;}}
  function navigate(id,{role,preserve=false}={}){
    const nextRole=role||(id.startsWith('A')?'admin':'usuario');
    if(!screens[nextRole]?.some(s=>s.id===id))return;
    if(id==='U07'&&!preserve){view.editId=null;view.recommendation=null;}
    if(id==='A04'&&!preserve)view.template=null;
    if(view.screen!==id||view.role!==nextRole)view.trail.push({role:view.role,screen:view.screen});
    view.role=nextRole;view.screen=id;
    history.pushState(null,'',`#${nextRole}/${id}`);
    render();
  }
  function relevantRecommendations(){
    const recordedDays=new Set(db.habits.flatMap(h=>Object.keys(h.logs)));
    if(!db.profile.consent||recordedDays.size<7)return [];
    return db.recommendations.filter(r=>r.active&&r.confidence>=db.config.confidence&&(!db.dismissed[r.id]||today>=db.dismissed[r.id])&&!db.habits.some(h=>normalize(h.name)===normalize(r.name)&&(!h.archived||h.archivedAt>=dateAt(-30)))&&!db.templates.some(t=>(t.id===r.templateId||normalize(t.name)===normalize(r.name))&&!t.active)).slice(0,db.config.cap);
  }
  function habitRow(h,withCheck=true){
    return `<div class="habit-item" style="--habit-color:${esc(h.color)}">${withCheck?action('toggle-habit',complete(h)?icon('check',15):icon('plus',14),`habit-check ${complete(h)?'done':''}`,`data-id="${h.id}" aria-label="${complete(h)?'Deshacer':'Completar'} ${esc(h.name)}"`):`<span class="habit-check">${icon('book',16)}</span>`}<button type="button" class="habit-open" data-action="open-habit" data-id="${h.id}"><strong>${esc(h.name)}${h.archived?' · Archivado':''}</strong><small>${esc(h.category)} · ${amount(h)} / ${h.target} ${esc(h.unit)}</small><div class="tiny-bar"><span style="width:${Math.min(amount(h)/h.target*100,100)}%"></span></div></button><span class="habit-arrow">›</span></div>`;
  }
  function welcome(){return `<div class="auth-shell"><div class="welcome-mark">${logo()}<span class="eyebrow">HÁBITOS QUE SE CONVIERTEN EN PROGRESO</span></div><div class="welcome-chart"><div class="screen-kicker"><span>PEQUEÑOS PASOS. CAMBIOS REALES.</span><span class="pill">Vista de ejemplo</span></div><svg viewBox="0 0 280 115" role="img" aria-label="Ilustración de una tendencia de constancia ascendente"><defs><linearGradient id="area" x2="0" y2="1"><stop stop-color="#1E54C9" stop-opacity=".16"/><stop offset="1" stop-color="#1E54C9" stop-opacity="0"/></linearGradient></defs><path d="M5 95H275M5 65H275M5 35H275" stroke="#d9e4f7" stroke-dasharray="3 5"/><path d="M5 95C32 95 28 75 57 77S92 90 112 61 147 67 166 40 208 54 226 24 254 40 275 10V113H5Z" fill="url(#area)"/><path d="M5 95C32 95 28 75 57 77S92 90 112 61 147 67 166 40 208 54 226 24 254 40 275 10" fill="none" stroke="#1E54C9" stroke-width="3"/><circle cx="275" cy="10" r="5" fill="#1E54C9"/></svg><div class="chart-summary"><span>Tu primer paso</span><span>Una rutina sostenible ↗</span></div></div><h1 class="welcome-heading">Tu mejor versión,<br><em>un hábito a la vez.</em></h1><p class="screen-subtitle">Construye una rutina a tu ritmo. Registra tus avances y encuentra claridad en cada pequeño logro.</p>${[['check','Seguimiento sin complicaciones','Tu progreso diario, siempre a la vista.'],['chart','Constancia que puedes ver','Historial y rachas con sentido.'],['spark','Un impulso personalizado','Sugerencias de IA que tú decides aceptar.']].map(([i,t,d])=>`<div class="feature"><span class="feature-icon">${icon(i)}</span><div><strong>${t}</strong><small>${d}</small></div></div>`).join('')}<div class="stack" style="margin-top:24px">${go('U03','Comenzar mi rutina '+icon('arrow',15))}${go('U02','Ya tengo cuenta','secondary')}</div><p class="form-note">Sin prisas. Sin comparaciones. Solo tu progreso.</p></div>`;}
  function login(admin=false){return `<div class="auth-shell">${heading(admin?'Espacio de administración':'Qué bueno verte de nuevo',admin?'Gestiona la operación, cuida la experiencia.':'Continúa construyendo la rutina que quieres.',admin?'ACCESO RESTRINGIDO':'BIENVENIDO A QUANTIFY CORE',`<span class="pill">${admin?'ADMIN':'USUARIO'}</span>`)}<div class="card" style="text-align:center;padding:24px">${icon(admin?'shield':'leaf',36)}<p style="margin-top:10px">${admin?'Herramientas globales. Privacidad personal.':'Cada día es una nueva oportunidad.'}</p></div><form id="${admin?'admin-login':'login'}" novalidate>${field('Correo electrónico','email','email',admin?'admin@quantify.demo':'alex@quantify.demo','required autocomplete="username"')}${field('Contraseña','password','password','Demo2026!','required minlength="8" autocomplete="current-password"')}${!admin?`<div style="text-align:right">${go('U04','Olvidé mi contraseña','text-link')}</div>`:''}${error()}<button class="primary full" type="submit">${admin?'Acceder al panel':'Iniciar sesión'} ${icon('arrow',15)}</button></form><div class="demo-credentials"><strong>Cuenta de demostración</strong><br>${admin?'admin':'alex'}@quantify.demo · Demo2026!<br>No se envían datos ni se autentica contra un servidor.</div>${!admin?`<p class="form-note">¿Tu primer día por aquí? ${go('U03','Crear una cuenta','text-link')}</p>`:note('La navegación lateral es una herramienta de revisión de sketches; no representa permisos reales de acceso.')} </div>`;}
  function register(){return `<div class="auth-shell">${heading('Comienza contigo','Crea tu cuenta de ejemplo y da forma a tus hábitos.','CREAR CUENTA','<span class="pill">Paso 1 de 2</span>')}<form id="register" novalidate>${field('Nombre','name','text','','required minlength="2" maxlength="60" autocomplete="name" placeholder="¿Cómo te llamas?"')}${field('Correo electrónico','email','email','','required autocomplete="email" placeholder="nombre@ejemplo.com"')}${field('Contraseña','password','password','','required minlength="8" autocomplete="new-password" placeholder="Mínimo 8 caracteres"')}<label class="check-field"><input type="checkbox" name="terms" required><span>Acepto usar datos ficticios en esta demostración. No ingresaré información personal ni contraseñas reales.</span></label>${error()}<button type="submit" class="primary full">Crear cuenta de ejemplo ${icon('arrow',15)}</button></form>${note('La verificación es simulada. No enviamos correos y la contraseña de prueba solo vive en memoria durante esta visita.')}<p class="form-note">¿Ya tienes cuenta? ${go('U02','Iniciar sesión','text-link')}</p></div>`;}
  function recover(){return `<div class="auth-shell">${heading('Recupera tu acceso','Solicita un código de ejemplo para continuar con el flujo.','RECUPERACIÓN DE CUENTA')}<div class="card" style="text-align:center;padding:28px">${icon('lock',38)}</div><form id="recover" novalidate>${field('Correo electrónico','email','email','alex@quantify.demo','required autocomplete="email"')}${error()}<button type="submit" class="primary full">Solicitar código de ejemplo</button></form>${note('Usa alex@quantify.demo o la cuenta creada en esta visita. El código de demostración es 123456; no se envía ningún correo.')}<div class="form-note">${go('U02','← Volver al inicio de sesión','text-link')}</div></div>`;}
  function verify(){return `<div class="auth-shell">${heading('Un paso más','Introduce el código de demostración para verificar tu '+(view.verify==='recover'?'solicitud de recuperación.':'nueva cuenta.'),'VERIFICACIÓN','<span class="pill">Paso 2 de 2</span>')}<div class="card" style="padding:30px;text-align:center">${icon('shield',42)}<p>Tu cuenta, bajo tu control.</p></div><form id="verify" novalidate>${field('Código de 6 dígitos','code','text','','required inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}" placeholder="123456"')}${error()}<button type="submit" class="primary full">Verificar y continuar</button></form><div class="demo-credentials">Código de prueba: <strong class="code">123456</strong><br>Este flujo no envía correos reales.</div><div class="form-note">${action('resend','Volver a mostrar el código','text-link')}<br>${go('U02','Cancelar verificación','text-link')}</div></div>`;}
  function resetPassword(){return `<div class="auth-shell">${heading('Nueva contraseña','Finaliza la recuperación de tu cuenta de demostración.','RECUPERACIÓN')}<form id="password" novalidate>${field('Nueva contraseña de prueba','password','password','','required minlength="8" autocomplete="new-password"')}${field('Confirmar contraseña','confirm','password','','required minlength="8" autocomplete="new-password"')}${error()}<button type="submit" class="primary full">Guardar y volver al acceso</button></form>${note('La clave de prueba no se guarda en localStorage. Al recargar, la cuenta de ejemplo vuelve a usar Demo2026!.')}</div>`;}
  function dashboard(){
    const all=todayHabits(),done=all.filter(h=>complete(h)).length,percent=all.length?Math.round(done/all.length*100):0;
    const categories=['Todos','Estudio','Salud','Productividad','Bienestar'];
    const list=all.filter(h=>view.filter==='Todos'||h.category===view.filter);
    return `${heading('Hoy cuenta, '+esc(db.profile.name.split(' ')[0])+'.','Miércoles, 14 de octubre · día de ejemplo','TU RUTINA, A TU RITMO',`<span class="pill">${Math.max(0,...activeHabits().map(streak))} días de racha</span>`)}<div class="columns"><div><div class="card progress-card"><div><span class="eyebrow">TU PROGRESO DE HOY</span><div class="big-number">${done} <small>de ${all.length} hábitos</small></div><p>${percent===100?'¡Tu rutina de hoy está completa!':'Cada pequeño avance suma.'}</p></div><div class="ring" style="--value:${percent}"><span>${percent}%<small>COMPLETADO</small></span></div></div><div class="card card-blue"><span class="eyebrow">UN IMPULSO PARA HOY</span><h3>La constancia empieza<br>con un paso posible.</h3><p>No necesitas hacerlo perfecto. Solo volver a intentarlo.</p>${go('U11','Explorar IA Coach '+icon('arrow',12),'text-link')}</div></div><div>${section('Tus hábitos de hoy',`${all.length} programados`)}<div class="filters">${categories.map(c=>action('filter-habits',esc(c),'',`data-value="${c}" aria-pressed="${view.filter===c}"`)).join('')}</div>${list.map(h=>habitRow(h)).join('')||`<div class="empty"><p>No hay hábitos programados en esta categoría.</p></div>`}<div style="text-align:right;margin-top:12px">${go('U07',icon('plus',14)+' Nuevo hábito')}</div></div></div>`;
  }
  function habitForm(){
    const h=db.habits.find(h=>h.id===view.editId),r=db.recommendations.find(r=>r.id===view.recommendation),v=h||r||{name:'',category:'Estudio',target:20,unit:'min',days:[0,1,2,3,4],color:'#1E54C9'};
    return `${heading(h?'Dale forma a tu hábito':r?'Hazlo parte de tu rutina':'Un nuevo comienzo','Define una meta pequeña, clara y posible.','CONFIGURACIÓN DE RUTINA',`<span class="pill">${h?'Editar':r?'Desde IA':'Nuevo hábito'}</span>`)}${r?note('Revisa la propuesta. La recomendación se acepta únicamente cuando guardas el hábito.'):''}<form id="habit-form" novalidate><div class="columns"><div class="card">${field('Nombre del hábito','name','text',v.name,'required minlength="3" maxlength="60" placeholder="Por ejemplo, lectura consciente"')}${select('Categoría','category',['Estudio','Salud','Productividad','Bienestar'],v.category)}<span class="field">Días de tu rutina</span>${daysInput(v.days||[0,1,2,3,4])}<p class="form-note" style="text-align:left">Los días de descanso no interrumpen tu racha.</p></div><div><div class="card"><h3>Una meta que puedes medir</h3><div class="field-row">${field('Cantidad','target','number',v.target,'required min="1" max="100000" step="1"')}${select('Unidad','unit',['min','ml','repeticiones','páginas'],v.unit)}</div>${field('Color del hábito','color','color',v.color||'#1E54C9')}<p>Podrás configurar un recordatorio después de guardar.</p></div>${note('Tu progreso del día se conserva al editar. Si reduces la meta, el avance se limita a la nueva cantidad; el historial previo conserva su meta original.')} </div></div>${error()}<div class="button-row">${action('cancel-habit','Cancelar','secondary')}<button type="submit" class="primary">${icon('check',14)} Guardar hábito</button></div></form>`;
  }
  function detail(){const h=habit();if(!h)return emptyRoutine();const percent=Math.round(amount(h)/h.target*100);return `${heading(esc(h.name),esc(h.category)+' · '+h.days.length+' días por semana','DETALLE DEL HÁBITO',`<span class="pill ${h.archived?'amber':''}">${h.archived?'Archivado':'Activo'}</span>`)}${h.archived?note('Este hábito está archivado. Puedes consultar su historial; no registrar nuevos avances.','warning'):''}<div class="card progress-card"><div><span class="eyebrow">AVANCE DEL DÍA</span><div class="big-number">${amount(h)} <small>/ ${h.target} ${esc(h.unit)}</small></div><p>${complete(h)?'Meta alcanzada. Bien hecho.':'Un paso a la vez.'}</p></div><div class="ring" style="--value:${Math.min(percent,100)}"><span>${Math.min(percent,100)}%<small>DE TU META</small></span></div></div><div class="metric-grid two">${metric('RACHA ACTUAL',streak(h),'Días programados cumplidos')}${metric('DÍAS CON REGISTROS',Object.keys(h.logs).length,'Historial conservado')}</div>${!h.archived?`<form id="progress-form" novalidate><div class="card" style="margin-top:14px"><h3>¿Cuánto avanzaste hoy?</h3>${field('Añadir avance ('+esc(h.unit)+')','amount','number',Math.min(h.unit==='ml'?250:5,Math.max(h.target-amount(h),1)),'required min="1" max="100000" step="1"')}${error()}<button type="submit" class="primary full" ${!scheduled(h)||complete(h)?'disabled':''}>${icon('plus',14)} Registrar avance</button><div class="button-row">${action('toggle-habit',complete(h)?'Deshacer el día':'Completar la meta','secondary',`data-id="${h.id}" ${!scheduled(h)?'disabled':''}`)}</div>${!scheduled(h)?'<p class="form-note">Este hábito no está programado para el día de ejemplo.</p>':''}</div></form>`:''}<div class="card"><div class="reminder-summary">${icon('clock',21)}<div><strong>${h.reminder.enabled?esc(h.reminder.time):'Sin recordatorio'}</strong><p>${h.reminder.enabled?'Aviso local simulado':'Puedes activar un horario a tu ritmo.'}</p></div>${!h.archived?go('U09','Ajustar','text-link','style="margin-left:auto"'):''}</div></div><div class="button-row">${!h.archived?action('edit-habit','Editar hábito','secondary'):''}${go('U10','Ver análisis','secondary')}</div>${!h.archived?`<div class="form-note">${go('U13',icon('archive',13)+' Archivar hábito','text-link')}</div>`:''}${go('U06','← Volver a Hoy','text-link')}`;}
  function reminder(){const h=habit();if(!h)return emptyRoutine();return `${heading('Un aviso a tu ritmo',esc(h.name),'RECORDATORIO')}<form id="reminder-form" novalidate><div class="card">${toggle('enabled','Activar recordatorio','No modifica la meta ni el progreso.',h.reminder.enabled)}${field('Horario del aviso','time','time',h.reminder.time,'required')}<span class="field">Días de aviso</span>${daysInput(h.reminder.days,h.days)}</div>${note('Solo puedes elegir días en los que el hábito está programado. Esta demo muestra la configuración; no solicita permisos ni envía notificaciones.')} ${error()}<div class="button-row">${go('U08','Cancelar','secondary')}<button class="primary" type="submit">Guardar horario</button></div></form>`;}
  function dailyPercent(day){const list=db.habits.filter(h=>(!h.createdAt||h.createdAt<=day)&&(!h.archivedAt||h.archivedAt>day)&&scheduled(h,day));return list.length?Math.round(list.filter(h=>complete(h,day)).length/list.length*100):0;}
  function analytics(){const values=Array.from({length:view.period},(_,i)=>dailyPercent(dateAt(i-view.period+1))),average=Math.round(values.reduce((a,b)=>a+b,0)/values.length);return `${heading('Mira todo lo que has avanzado','Tus pequeños pasos, vistos con perspectiva.','ANÁLISIS DE TU RUTINA')}<div class="filters">${[7,14].map(n=>action('period',n+' días','',`data-value="${n}" aria-pressed="${view.period===n}"`)).join('')}</div><div class="metric-grid two">${metric('CUMPLIMIENTO MEDIO',average+'%','Del periodo seleccionado')}${metric('MEJOR RACHA ACTUAL',Math.max(0,...db.habits.map(streak)),'Días programados')}</div><div class="columns"><div><div class="card" style="margin-top:14px"><h3>Tu constancia, día a día</h3><p>Porcentaje de hábitos programados cumplidos.</p><div class="bar-chart">${values.map((v,i)=>`<div class="bar-col" style="--height:${v}" title="${dateAt(i-view.period+1)}: ${v}%"><span>${v}%</span><div class="bar"></div><small>${new Date(dateAt(i-view.period+1)+'T12:00:00').getDate()}</small></div>`).join('')}</div></div><div class="card"><h3>Últimos 28 días</h3><p>Cada celda es un día, de izquierda a derecha.</p><div class="heatmap">${Array.from({length:28},(_,i)=>{const d=dateAt(i-27),v=dailyPercent(d);return `<span class="level${v===0?0:v<50?1:v<100?2:3}" title="${d}: ${v}%">${new Date(d+'T12:00:00').getDate()}</span>`;}).join('')}</div><p>Menor intensidad → mayor cumplimiento</p></div></div><div>${section('Historial de hábitos','Incluye archivados')}${db.habits.map(h=>habitRow(h,false)).join('')}</div></div>`;}
  function coach(){const list=relevantRecommendations();return `${heading('Un impulso, no una exigencia','Ideas para acompañar tu rutina. Tú decides qué sumar.','IA COACH · SUGERENCIAS SIMULADAS','<span class="pill">Personalizado</span>')}<div class="card card-dark"><span class="eyebrow">BASADO EN TU HISTORIAL DE EJEMPLO</span><h3>Haz espacio para lo que te hace bien.</h3><p>Explicamos cada propuesta. Tu rutina nunca cambia sin que lo confirmes.</p></div>${!db.profile.consent?`<div class="empty">${icon('shield',30)}<h3>Tu privacidad va primero</h3><p>Activa el análisis de patrones si quieres ver estas sugerencias de ejemplo.</p>${go('U12','Revisar consentimiento','secondary')}</div>`:!list.length?`<div class="empty">${icon('spark',30)}<h3>Por ahora, todo en calma</h3><p>No hay sugerencias que cumplan las reglas. Puede que ya las hayas incorporado, descartado o que estén pausadas.</p>${go('U06','Volver a mi rutina','secondary')}</div>`:`${section('Ideas para tu rutina',list.length+' disponibles')}<div class="columns">${list.map(r=>`<article class="card coach-card"><div class="confidence">${icon('spark',12)} ${r.confidence}% de afinidad · ejemplo</div><h3>${esc(r.name)}</h3><p>${esc(r.category)} · ${r.target} ${esc(r.unit)} al día</p><div class="why"><strong>¿Por qué esta idea?</strong><br>${esc(r.reason)}</div><div class="button-row">${action('accept-recommendation','Personalizar','primary',`data-id="${r.id}"`)}${action('dismiss-recommendation','Descartar','secondary',`data-id="${r.id}"`)}</div></article>`).join('')}</div>`}${note('Máximo '+db.config.cap+' sugerencias · confianza ≥ '+db.config.confidence+'% · descartar oculta la propuesta durante 21 días. La IA de esta práctica es simulada.')}`;}
  function settings(){return `${heading('Tu espacio, tus preferencias','Elige cómo quieres acompañar tu progreso.','PERFIL Y AJUSTES')}<div class="profile"><span class="avatar">${esc(db.profile.name.slice(0,2).toUpperCase())}</span><div><h3>${esc(db.profile.name)}</h3><p>Perfil de demostración · datos locales</p></div></div><form id="preferences" novalidate><div class="columns"><div><div class="card"><h3>Preferencias personales</h3>${field('Nombre de ejemplo','name','text',db.profile.name,'required minlength="2" maxlength="60"')}${toggle('push','Avisos de hábitos','Permite ver avisos de ejemplo en el centro.',db.profile.push)}${toggle('summary','Resumen diario','Preferencia simulada, sin envíos reales.',db.profile.summary)}</div>${go('U14',icon('bell',14)+' Ver centro de avisos','secondary full')}</div><div><div class="card"><h3>Privacidad e inteligencia artificial</h3>${toggle('consent','Análisis de patrones para IA','Puedes retirarlo en cualquier momento. No elimina tus hábitos.',db.profile.consent)}<p>Administración consulta métricas agregadas, no tu rutina personal. Este prototipo no conecta con servicios externos.</p></div>${note('Móvil y PWA son dos formatos del mismo recorrido. Tus preferencias y avances se conservan al alternar.')}</div></div>${error()}<button class="primary full" type="submit">Guardar preferencias</button></form><div class="form-note">${action('logout-user','Cerrar sesión de demostración','text-link')}</div>`;}
  function archiveScreen(){const h=habit();if(!h)return emptyRoutine();return `${heading('Haz espacio en tu rutina','Archivar también puede ser parte del progreso.','ARCHIVAR HÁBITO')}<div class="card"><span class="pill amber">Confirmación necesaria</span><h3 style="font-size:19px;margin-top:15px">${esc(h.name)}</h3><p>Este hábito dejará de aparecer en tu lista diaria. Su historial se conserva en Análisis y no se podrán registrar nuevos avances.</p></div>${note('La acción no borra tus registros ni modifica las plantillas del catálogo.','warning')}<div class="button-row">${go('U08','Conservar hábito','secondary')}${action('archive-habit','Confirmar archivo','danger-button')}</div>`;}
  function notices(){const items=[{id:'n1',title:'Un momento para leer',text:'Tu recordatorio de lectura consciente está configurado a las 08:00.',habit:'h1',time:'08:00 · aviso de ejemplo'},{id:'n2',title:'Tu progreso merece una pausa',text:'Revisa cómo va tu hidratación de hoy.',habit:'h2',time:'10:00 · aviso de ejemplo'}];return `${heading('Pequeños recordatorios','Avisos de ejemplo. No son notificaciones del dispositivo.','CENTRO DE AVISOS')}${!db.profile.push?`<div class="empty">${icon('bell',30)}<h3>Los avisos están desactivados</h3><p>Puedes cambiarlo cuando quieras.</p>${go('U12','Revisar preferencias','secondary')}</div>`:items.map(n=>`<div class="card notice-item ${db.readNotices.includes(n.id)?'read':''}"><small>${n.time}</small><h3>${n.title}</h3><p>${n.text}</p><div class="button-row">${action('notice-habit','Ver hábito','text-link',`data-id="${n.habit}" data-notice="${n.id}"`)}${db.readNotices.includes(n.id)?'<span class="pill green">Leído</span>':action('read-notice','Marcar leído','text-link',`data-id="${n.id}"`)}</div></div>`).join('')}${go('U12','Preferencias de avisos','secondary full')}`;}
  const emptyRoutine=()=>`<div class="empty"><h3>Tu rutina comienza aquí</h3><p>Crea un hábito para explorar este recorrido.</p>${go('U07','Crear hábito')}</div>`;
  function adminDashboard(){return `${heading('Una visión de conjunto','Operación de Quantify Core · corte ilustrativo','RESUMEN OPERATIVO','<span class="pill green">Servicios estables</span>')}<div class="metric-grid">${metric('CUENTAS ACTIVAS','1,284','Datos de ejemplo')}${metric('RETENCIÓN SEMANAL','76%','Datos de ejemplo')}${metric('ACEPTACIÓN IA','64%','Datos de ejemplo')}${metric('CAMBIOS EN ESTA DEMO',db.audit.length,'Auditoría local')}</div>${note('Las métricas de plataforma son ilustrativas y agregadas. No corresponden a personas reales. El catálogo y la auditoría sí reflejan tus acciones en esta demo.')}<div class="columns"><div><div class="card card-blue"><span class="eyebrow">CALIDAD DE LA EXPERIENCIA</span><h3>Catálogo claro.<br>Hábitos posibles.</h3><p>${db.templates.filter(t=>t.active).length} plantillas activas en esta demostración.</p>${go('A03','Gestionar catálogo '+icon('arrow',13),'text-link')}</div><div class="card"><h3>Estado de servicios · ejemplo</h3><div class="list-row"><span>Acceso y sincronización</span><span class="pill green">Operativo</span></div><div class="list-row"><span>Motor de sugerencias</span><span class="pill green">Operativo</span></div><div class="list-row"><span>Despacho de avisos</span><span class="pill green">Operativo</span></div></div></div><div><div class="card"><h3>Control con contexto</h3><p>Pausa sugerencias, revisa cambios y administra accesos con un motivo documentado.</p><div class="stack" style="margin-top:16px">${go('A05',icon('spark',14)+' Supervisar IA','secondary')}${go('A07',icon('users',14)+' Control de accesos','secondary')}${go('A06',icon('list',14)+' Consultar auditoría','secondary')}${go('A08',icon('settings',14)+' Configuración global','secondary')}</div></div></div></div>`;}
  function catalog(){return `${heading('Buenas rutinas empiezan aquí','Plantillas reutilizables; cada usuario personaliza su copia.','CATÁLOGO DE HÁBITOS',`<span class="pill">${db.templates.length} plantillas</span>`)}<div style="text-align:right;margin-bottom:15px">${go('A04',icon('plus',14)+' Nueva plantilla')}</div><div class="columns">${db.templates.map(t=>`<article class="card"><div class="screen-kicker"><span>${esc(t.category)}</span><span class="pill ${t.active?'green':'amber'}">${t.active?'Activa':'Pausada'}</span></div><h3 style="font-size:15px">${esc(t.name)}</h3><p>Meta sugerida: ${t.target} ${esc(t.unit)} por día</p><div class="button-row">${action('edit-template','Editar','secondary',`data-id="${t.id}"`)}${action('toggle-template',t.active?'Pausar':'Reactivar','secondary',`data-id="${t.id}"`)}</div></article>`).join('')}</div>${note('Pausar una plantilla impide ofrecer nuevas sugerencias asociadas. Las rutinas ya creadas no se alteran.')}`;}
  function templateForm(){const t=db.templates.find(t=>t.id===view.template)||{name:'',category:'Estudio',target:20,unit:'min'};return `${heading(view.template?'Mejora una plantilla':'Una nueva opción para crecer','Los cambios solo afectan futuras propuestas del catálogo.','EDICIÓN DEL CATÁLOGO')}<form id="template-form" novalidate><div class="card">${field('Nombre de la plantilla','name','text',t.name,'required minlength="3" maxlength="60"')}${select('Categoría','category',['Estudio','Salud','Productividad','Bienestar'],t.category)}<div class="field-row">${field('Meta sugerida','target','number',t.target,'required min="1" max="100000" step="1"')}${select('Unidad','unit',['min','ml','repeticiones','páginas'],t.unit)}</div><label class="field">Motivo del cambio<textarea name="reason" required minlength="8" maxlength="240" placeholder="Describe qué mejora aporta esta modificación"></textarea></label></div>${error()}<div class="button-row">${go('A03','Cancelar','secondary')}<button class="primary" type="submit">Guardar plantilla</button></div></form><div class="form-note">${go('A05','Abrir supervisión de IA','text-link')}</div>`;}
  function supervision(){return `${heading('IA con supervisión humana','Evalúa la propuesta, conserva el control.','CALIDAD DE RECOMENDACIONES')}<div class="metric-grid two">${metric('ACEPTADAS · EJEMPLO','64%','Agregado ilustrativo')}${metric('DESCARTADAS · EJEMPLO','36%','Agregado ilustrativo')}</div>${note('Solo se presentan métricas agregadas y contenido de plantillas. No se muestran identidades ni hábitos de usuarios.')}<div class="columns">${db.recommendations.map(r=>`<article class="card"><div class="screen-kicker"><span>PROPUESTA ${r.id.toUpperCase()}</span><span class="pill ${r.active?'green':'amber'}">${r.active?'Activa':'Pausada'}</span></div><h3>${esc(r.name)}</h3><p>${esc(r.reason)}</p><div class="list-row"><span>Confianza de ejemplo</span><strong>${r.confidence}%</strong></div>${action('toggle-recommendation',r.active?'Pausar recomendación':'Reactivar recomendación','secondary full',`data-id="${r.id}"`)}</article>`).join('')}</div>${go('A06','Ver historial de decisiones '+icon('arrow',13),'text-link')}`;}
  function audit(){const list=db.audit.filter(e=>view.auditFilter==='Todas'||e.action===view.auditFilter);return `${heading('Cada cambio tiene una historia','Registro local de acciones administrativas de esta demo.','AUDITORÍA',`<span class="pill">${db.audit.length} eventos</span>`)}<label class="field">Filtrar por acción<select id="audit-filter">${options(['Todas',...new Set(db.audit.map(e=>e.action))],view.auditFilter)}</select></label>${!list.length?`<div class="empty">${icon('list',30)}<h3>Sin cambios registrados</h3><p>Las modificaciones al catálogo, a IA, accesos y configuración aparecerán aquí.</p>${go('A03','Explorar catálogo','secondary')}</div>`:`<div class="card">${list.map(e=>`<div class="audit-event"><strong>${esc(e.action)} · ${esc(e.entity)}</strong><time datetime="${esc(e.at)}">${esc(new Date(e.at).toLocaleString('es-MX',{timeZone:'America/Mexico_City'}))}</time><p>${esc(e.reason)}<br>Responsable: ${e.actor}</p></div>`).join('')}</div>`}${note('No hay controles para borrar ni editar eventos. Restablecer la demo elimina todos los datos de ejemplo, incluida esta auditoría; no es un registro de producción.')}`;}
  function accounts(){return `${heading('Accesos bajo control','Cuentas ficticias, sin datos personales ni rutinas.','CONTROL DE ACCESOS')}${db.accounts.map(a=>`<div class="card account-row"><span class="avatar">${icon(a.self?'shield':'users',17)}</span><div><strong class="code">${a.id}</strong><small>${a.self?'Administrador actual':'Usuario de ejemplo'}</small><span class="pill ${a.active?'green':'amber'}" style="margin-top:7px">${a.active?'Activa':'Suspendida'}</span></div>${a.self?'<span class="pill">Protegida</span>':action('account-change',a.active?'Suspender':'Reactivar','secondary',`data-id="${a.id}"`)}</div>`).join('')}${note('La suspensión cambia únicamente el estado de la cuenta ficticia y se audita. No elimina registros ni permite consultar hábitos. No se conecta con autenticación real.')}`;}
  function globalSettings(){return `${heading('Límites que cuidan la experiencia','Configura la demostración sin reducir sus criterios mínimos.','CONFIGURACIÓN GLOBAL')}<form id="global-settings" novalidate><div class="card">${field('Confianza mínima de sugerencias (%)','confidence','number',db.config.confidence,'required min="80" max="99" step="1"')}${select('Máximo de sugerencias pendientes','cap',['1','2'],String(db.config.cap))}<label class="field">Motivo del ajuste<textarea name="reason" required minlength="8" maxlength="240" placeholder="Explica por qué se modifica este límite"></textarea></label></div>${note('El mínimo es 80% y el máximo es 2 sugerencias. Estos valores afectan las propuestas visibles en el rol Usuario. No se recolectan datos externos.')} ${error()}<button class="primary full" type="submit">Guardar y registrar en auditoría</button></form><div class="form-note">${go('A01','Cerrar sesión administrativa','text-link')}</div>`;}
  function accountConfirm(){const a=db.accounts.find(a=>a.id===view.account)||db.accounts[0];return `${heading(a.active?'Suspender acceso':'Reactivar acceso','Revisa la cuenta antes de confirmar el cambio.','CONFIRMACIÓN ADMINISTRATIVA')}<div class="card"><h3 class="code">${a.id}</h3><p>${a.active?'Esta cuenta de ejemplo pasará a estado suspendido.':'Esta cuenta de ejemplo recuperará el estado activo.'} Sus datos se conservan.</p></div><form id="account-confirm" novalidate><label class="field">Motivo obligatorio<textarea name="reason" required minlength="8" maxlength="240" placeholder="Describe la razón del cambio de acceso"></textarea></label>${error()}<div class="button-row">${go('A07','Cancelar','secondary')}<button class="${a.active?'danger-button':'primary'}" type="submit">Confirmar ${a.active?'suspensión':'reactivación'}</button></div></form>${note('La cuenta ADM-001 está protegida y no puede suspenderse desde este recorrido.','warning')}`;}
  const renderers={U01:welcome,U02:()=>login(),U03:register,U04:recover,U05:verify,U06:dashboard,U07:habitForm,U08:detail,U09:reminder,U10:analytics,U11:coach,U12:settings,U13:archiveScreen,U14:notices,U15:resetPassword,A01:()=>login(true),A02:adminDashboard,A03:catalog,A04:templateForm,A05:supervision,A06:audit,A07:accounts,A08:globalSettings,A09:accountConfirm};
  function navItems(){return view.role==='usuario'?[['U06','Hoy','home'],['U10','Análisis','chart'],['U11','IA Coach','spark'],['U12','Ajustes','settings']]:[['A02','Resumen','home'],['A03','Catálogo','book'],['A05','IA','spark'],['A06','Auditoría','list'],['A07','Cuentas','users'],['A08','Ajustes','settings']];}
  function isActiveNav(id){if(id==='U06')return ['U06','U07','U08','U09','U13','U14'].includes(view.screen);if(id==='A03')return ['A03','A04'].includes(view.screen);if(id==='A07')return ['A07','A09'].includes(view.screen);return view.screen===id;}
  function render(){
    const current=screens[view.role].find(s=>s.id===view.screen);
    $('#screen-count').textContent=screens[view.role].length;
    $('#screen-list').innerHTML=[...new Set(screens[view.role].map(s=>s.group))].map(group=>`<div class="nav-group">${group}</div>`+screens[view.role].filter(s=>s.group===group).map(s=>`<button type="button" class="screen-link" data-review="${s.id}" ${s.id===view.screen?'aria-current="page"':''}><span>${s.id}</span>${s.title}</button>`).join('')).join('');
    $('#screen-code').textContent=`${view.screen} / ${view.role==='usuario'?'USUARIO':'ADMINISTRADOR'}`;
    $('#screen-title').textContent=current.title;
    $$('[data-role]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.role===view.role));
    const auth=current.group==='Acceso';const nav=navItems().map(([id,label,i])=>go(id,icon(i)+`<span>${label}</span>`,'',`${isActiveNav(id)?'aria-current="page"':''}`)).join('');
    $('#app').innerHTML=`<aside class="app-sidebar ${auth?'auth':''}" aria-label="Navegación del ${view.role==='admin'?'administrador':'usuario'}">${logo()}${nav}<small>Quantify Core<br>Prototipo · Práctica 07</small></aside><div class="app-page"><header class="app-topbar">${auth?go(view.role==='admin'?'A01':'U01',icon('back',16),'icon-button','aria-label="Volver al acceso"'):logo()}<strong>${auth?(view.role==='admin'?'Administración':'Tu espacio de hábitos'):(view.role==='admin'?'Operación':'Mi rutina')}</strong><span class="sync"><span class="status-dot"></span>DEMO LOCAL</span>${!auth&&view.role==='usuario'?go('U14',icon('bell',15),'icon-button','aria-label="Centro de avisos"'):''}<span class="avatar">${view.role==='admin'?'AD':esc(db.profile.name.slice(0,1))}</span></header><div class="screen-scroll" id="screen-content" tabindex="-1">${renderers[view.screen]()}</div>${!auth?`<nav class="bottom-nav" aria-label="Secciones de la aplicación">${nav}</nav>`:''}</div>`;
    $('#inspector-content').innerHTML=`<span class="eyebrow">${current.group.toUpperCase()} / ${current.id}</span><h2>Desde aquí<br>puedes ir a…</h2><p class="description">${current.description}</p>${current.edges.map(e=>`<button type="button" class="connection ${e.kind==='state'?'state':''}" data-review="${e.to}" ${e.kind==='state'?'data-state="true"':''}><span class="route-code">${e.kind==='state'?'↻':e.to}</span><span><strong>${e.label}</strong><small>${e.kind==='state'?'Permanece en este sketch':screens[view.role].find(s=>s.id===e.to)?.title}</small></span></button>`).join('')}<div class="context-note"><span class="eyebrow">REGLAS DE ESTE RECORRIDO</span>${current.rules.map(id=>`<span class="rule-chip" title="${esc(rules.find(r=>r.id===id).text)}">${id}</span>`).join('')}<p>${rules.filter(r=>current.rules.includes(r.id)).map(r=>r.title).join(' · ')}.</p>El menú de sketches permite revisar pantallas directamente. Las condiciones se prueban en los botones y formularios del dispositivo.</div>`;
    $('#all-rules').innerHTML=rules.map(r=>`<p><strong>${r.id} · ${r.title}</strong><br>${r.text}</p>`).join('');
    $('#journey').textContent=view.trail.length?view.trail.slice(-3).map(t=>t.screen).concat(view.screen).join(' → '):'Inicio del recorrido';
    $('#go-back').disabled=!view.trail.length;
    $('#device').className='device '+view.platform;
  }
  function setFormError(form,message){$('.form-error',form).textContent=message;$('.form-error',form).scrollIntoView({block:'nearest'});}
  function validate(form){if(form.checkValidity())return true;const el=$$('input,select,textarea',form).find(e=>!e.validity.valid);setFormError(form,el?.validity.typeMismatch?'Escribe un correo electrónico válido.':'Revisa los campos: completa los obligatorios y respeta los límites indicados.');el?.focus();return false;}
  function validHabit(data,id,collection){const name=String(data.get('name')).trim(),target=Number(data.get('target'));if(name.length<3||name.length>60)return 'El nombre debe tener entre 3 y 60 caracteres.';if(!Number.isInteger(target)||target<1||target>100000)return 'La meta debe ser un entero entre 1 y 100000.';if(collection.some(h=>h.id!==id&&!h.archived&&normalize(h.name)===normalize(name)))return 'Ya existe un hábito o plantilla con ese nombre.';return '';}
  function submit(form){
    if(!validate(form))return;const data=new FormData(form);const fail=message=>setFormError(form,message);
    switch(form.id){
      case 'login':{const email=normalize(data.get('email')),pass=data.get('password');if(!((email==='alex@quantify.demo'&&pass===sessionPassword)||(registered&&email===normalize(registered.email)&&pass===registered.password)))return fail('Credenciales incorrectas. Usa la cuenta de ejemplo o la creada durante esta visita.');navigate('U06');toast('Sesión de demostración iniciada.');break;}
      case 'admin-login':if(normalize(data.get('email'))!=='admin@quantify.demo'||data.get('password')!=='Demo2026!')return fail('Acceso denegado. Usa la cuenta administrativa de demostración.');navigate('A02');toast('Vista administrativa de demostración.');break;
      case 'register':if(normalize(data.get('email'))==='admin@quantify.demo')return fail('El registro público no puede crear cuentas administrativas.');if(normalize(data.get('email'))==='alex@quantify.demo')return fail('Esta cuenta de ejemplo ya existe. Inicia sesión o recupera el acceso.');registered={name:String(data.get('name')).trim(),email:data.get('email'),password:data.get('password')};view.verify='register';navigate('U05');break;
      case 'recover':recoveryEmail=normalize(data.get('email'));if(recoveryEmail!=='alex@quantify.demo'&&recoveryEmail!==normalize(registered?.email||''))return fail('Usa la cuenta de ejemplo o una creada durante esta visita.');view.verify='recover';verifiedRecovery=false;navigate('U05');toast('Código de ejemplo: 123456. No se envió ningún correo.');break;
      case 'verify':if(data.get('code')!=='123456')return fail('Código incorrecto. En esta demo el código válido es 123456.');if(view.verify==='recover'){verifiedRecovery=true;navigate('U15');}else{if(registered){db.profile.name=registered.name;save();}navigate('U06');toast('Cuenta de ejemplo verificada.');}break;
      case 'password':if(!verifiedRecovery)return fail('Primero completa la verificación de recuperación desde Iniciar sesión.');if(data.get('password')!==data.get('confirm'))return fail('Las contraseñas no coinciden.');if(recoveryEmail==='alex@quantify.demo')sessionPassword=data.get('password');else if(registered)registered.password=data.get('password');verifiedRecovery=false;navigate('U02');toast('Clave de prueba actualizada solo para esta visita.');break;
      case 'habit-form':{
        const err=validHabit(data,view.editId,db.habits);if(err)return fail(err);const selectedDays=data.getAll('days').map(Number);if(!selectedDays.length)return fail('Selecciona al menos un día de tu rutina.');
        const r=db.recommendations.find(r=>r.id===view.recommendation);if(r&&!relevantRecommendations().some(x=>x.id===r.id))return fail('La sugerencia ya no está disponible. Vuelve a IA Coach.');
        if(r&&db.habits.some(h=>normalize(h.name)===normalize(data.get('name'))&&h.archivedAt>=dateAt(-30)))return fail('Este hábito se archivó hace menos de 30 días. Elige otra propuesta.');
        const values={name:String(data.get('name')).trim(),category:data.get('category'),target:Number(data.get('target')),unit:data.get('unit'),days:selectedDays,color:data.get('color')};
        let h=db.habits.find(h=>h.id===view.editId);if(h?.archived)return fail('No se puede editar un hábito archivado.');
        if(h){h.targetByDate??={};h.daysByDate??={};for(let i=-365;i<0;i++){const d=dateAt(i);h.targetByDate[d]??=h.target;h.daysByDate[d]??=[...h.days];}Object.assign(h,values);h.logs[today]=Math.min(h.logs[today]||0,h.target);h.reminder.days=h.reminder.days.filter(d=>h.days.includes(d));if(!h.reminder.days.length)h.reminder.enabled=false;}
        else{h={id:'h'+Date.now(),...values,createdAt:today,logs:{},reminder:{enabled:false,time:'08:00',days:selectedDays},source:r?.id};db.habits.push(h);}
        view.selected=h.id;view.editId=null;view.recommendation=null;save();navigate('U08');toast('Hábito guardado. Tu rutina está actualizada.');break;
      }
      case 'progress-form':{const h=habit();if(h.archived||!scheduled(h))return fail('No se puede registrar avance en este hábito hoy.');h.logs[today]=Math.min(h.target,amount(h)+Number(data.get('amount')));save();render();toast(complete(h)?'¡Meta alcanzada! Un único cumplimiento para hoy.':'Avance guardado. Cada paso suma.');break;}
      case 'reminder-form':{const h=habit(),chosen=data.getAll('days').map(Number),enabled=data.has('enabled');if(h.archived)return fail('El hábito está archivado.');if(enabled&&!chosen.length)return fail('Elige al menos un día para el aviso.');if(chosen.some(d=>!h.days.includes(d)))return fail('El aviso debe coincidir con un día programado.');h.reminder={enabled,time:data.get('time'),days:chosen};save();navigate('U08');toast('Recordatorio de ejemplo guardado.');break;}
      case 'preferences':db.profile={name:String(data.get('name')).trim(),consent:data.has('consent'),push:data.has('push'),summary:data.has('summary')};save();render();toast('Preferencias guardadas en este navegador.');break;
      case 'template-form':{const err=validHabit(data,view.template,db.templates);if(err)return fail(err);const reason=String(data.get('reason')).trim();if(reason.length<8)return fail('Describe el motivo con al menos 8 caracteres.');let t=db.templates.find(t=>t.id===view.template);const name=String(data.get('name')).trim();if(t){Object.assign(t,{name,category:data.get('category'),target:Number(data.get('target')),unit:data.get('unit')});db.recommendations.filter(r=>r.templateId===t.id).forEach(r=>Object.assign(r,{name:t.name,category:t.category,target:t.target,unit:t.unit}));}else{t={id:'t'+Date.now(),name,category:data.get('category'),target:Number(data.get('target')),unit:data.get('unit'),active:true};db.templates.push(t);}log(t.name,'Guardar plantilla',reason);navigate('A03');toast('Plantilla guardada y cambio auditado.');break;}
      case 'global-settings':{const reason=String(data.get('reason')).trim();if(reason.length<8)return fail('Describe el motivo con al menos 8 caracteres.');db.config={confidence:Number(data.get('confidence')),cap:Number(data.get('cap'))};log('Configuración IA','Guardar límites',`${reason} · confianza ${db.config.confidence}%, máximo ${db.config.cap}.`);render();toast('Configuración aplicada a las sugerencias de esta demo.');break;}
      case 'account-confirm':{const a=db.accounts.find(a=>a.id===view.account);if(!a||a.self)return fail('La cuenta administrativa actual está protegida.');const reason=String(data.get('reason')).trim();if(reason.length<8)return fail('Describe el motivo con al menos 8 caracteres.');a.active=!a.active;log(a.id,a.active?'Reactivar cuenta':'Suspender cuenta',reason);navigate('A07');toast('Estado de cuenta actualizado y auditado.');break;}
    }
  }
  function confirmation({title,text,reason=false,onConfirm,danger=false,label='Confirmar'}){
    confirmAction=onConfirm;$('#confirm-content').innerHTML=`<span class="eyebrow">CONFIRMACIÓN</span><h2 id="confirm-title">${esc(title)}</h2><p>${esc(text)}</p><form id="modal-confirm" novalidate>${reason?'<label class="field">Motivo del cambio<textarea name="reason" required minlength="8" maxlength="240" placeholder="Al menos 8 caracteres"></textarea></label>':''}${error()}<div class="button-row"><button type="button" class="secondary" data-close="confirm-dialog">Cancelar</button><button class="${danger?'danger-button':'primary'}" type="submit">${esc(label)}</button></div></form>`;$('#confirm-dialog').showModal();
  }
  function handleAction(name,el){const id=el.dataset.id;
    switch(name){
      case 'toggle-habit':{const h=db.habits.find(h=>h.id===id);if(!h||h.archived||!scheduled(h))return toast('Este hábito no está activo o programado hoy.');h.logs[today]=complete(h)?0:h.target;save();render();toast(complete(h)?'Hábito completado. ¡Un paso más!':'Registro del día deshecho.');break;}
      case 'open-habit':view.selected=id;navigate('U08');break;
      case 'filter-habits':view.filter=el.dataset.value;render();break;
      case 'edit-habit':view.editId=habit().id;view.recommendation=null;navigate('U07',{preserve:true});break;
      case 'cancel-habit':{const editing=!!view.editId;view.editId=null;view.recommendation=null;navigate(editing?'U08':'U06');break;}
      case 'archive-habit':{const h=habit();if(!h||h.archived)return toast('Este hábito ya está archivado.');h.archived=true;h.archivedAt=today;h.reminder.enabled=false;save();navigate('U06');toast('Hábito archivado. Su historial se conserva.');break;}
      case 'period':view.period=Number(el.dataset.value);render();break;
      case 'accept-recommendation':view.recommendation=id;view.editId=null;navigate('U07',{preserve:true});break;
      case 'dismiss-recommendation':db.dismissed[id]=dateAt(21);save();render();toast('Sugerencia descartada. No aparecerá durante 21 días.');break;
      case 'resend':toast('Código de demostración: 123456. No se envían correos.');break;
      case 'logout-user':navigate('U02');toast('Sesión de demostración cerrada. Los hábitos de ejemplo se conservan.');break;
      case 'read-notice':if(!db.readNotices.includes(id))db.readNotices.push(id);save();render();break;
      case 'notice-habit':if(!db.readNotices.includes(el.dataset.notice))db.readNotices.push(el.dataset.notice);view.selected=id;save();navigate('U08');break;
      case 'edit-template':view.template=id;navigate('A04',{preserve:true});break;
      case 'toggle-template':{const t=db.templates.find(t=>t.id===id);confirmation({title:t.active?'¿Pausar esta plantilla?':'¿Reactivar esta plantilla?',text:t.name+'. Los hábitos personales ya creados se conservan.',reason:true,onConfirm:reason=>{t.active=!t.active;log(t.name,t.active?'Reactivar plantilla':'Pausar plantilla',reason);render();toast('Estado actualizado y auditado.');}});break;}
      case 'toggle-recommendation':{const r=db.recommendations.find(r=>r.id===id);confirmation({title:r.active?'¿Pausar esta recomendación?':'¿Reactivar esta recomendación?',text:r.name+'. El cambio afecta las propuestas disponibles para nuevas aceptaciones.',reason:true,onConfirm:reason=>{r.active=!r.active;log(r.name,r.active?'Reactivar recomendación':'Pausar recomendación',reason);render();toast('Supervisión registrada en auditoría.');}});break;}
      case 'account-change':view.account=id;navigate('A09');break;
    }
  }
  function review(id){if(id==='U07'){view.editId=null;view.recommendation=null;}if(id==='A04')view.template='t1';if(id==='U05')view.verify='register';navigate(id,{preserve:true});}
  function openMap(){
    const list=screens[view.role];$('#map-title').textContent='Recorrido del '+(view.role==='admin'?'administrador':'usuario');
    const groups=[...new Set(list.map(s=>s.group))];const positions={};groups.forEach((g,col)=>list.filter(s=>s.group===g).forEach((s,row)=>positions[s.id]={x:28+col*235,y:50+row*72}));
    const height=70+Math.max(...groups.map(g=>list.filter(s=>s.group===g).length))*72;const width=groups.length*235+20;
    // Las flechas enfocan las salidas del sketch actual; las tarjetas enumeran el grafo completo.
    const focused=list.find(s=>s.id===view.screen),uniqueEdges=focused.edges.filter((e,i,a)=>e.to!==focused.id&&a.findIndex(x=>x.to===e.to)===i);
    const arrows=uniqueEdges.map(e=>{const a=positions[focused.id],b=positions[e.to];let path;if(a.x===b.x){const x=a.x+219;path=`M${a.x+205} ${a.y+28}H${x}V${b.y+28}H${b.x+205}`;}else if(b.x>a.x){const x=a.x+220;path=`M${a.x+205} ${a.y+28}H${x}V${b.y+28}H${b.x}`;}else{const x=b.x+220;path=`M${a.x} ${a.y+28}H${x}V${b.y+28}H${b.x+205}`;}return `<path d="${path}" fill="none" stroke="#1e54c9" stroke-opacity=".65" stroke-width="1.7" marker-end="url(#map-arrow)"><title>${esc(e.label)} → ${e.to}</title></path>`;}).join('');
    $('#map-visual').innerHTML=`<p class="map-help"><strong>Flechas: salidas de ${focused.id} · ${focused.title}.</strong> Abre otro sketch y vuelve al mapa para enfocar sus conexiones. Los retornos y condiciones están detallados abajo.</p><svg class="map-svg" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="map-svg-title"><title id="map-svg-title">Sketches por etapa y conexiones salientes de ${focused.id}. Las acciones se detallan en las tarjetas.</title><defs><marker id="map-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 7 3.5 0 7Z" fill="#1e54c9"/></marker></defs>${groups.map((g,i)=>`<text x="${28+i*235}" y="27" font-size="11" fill="#7687a1" font-weight="700">${esc(g.toUpperCase())}</text>`).join('')}${arrows}${list.map(s=>{const {x,y}=positions[s.id];return `<g class="map-node" tabindex="0" role="link" aria-label="Abrir ${s.id} ${esc(s.title)}" data-map-screen="${s.id}"><rect x="${x}" y="${y}" width="205" height="55" rx="8" fill="${s.id===view.screen?'#e9f0ff':'#f7f9fd'}" stroke="${s.id===view.screen?'#1e54c9':'#dce4f0'}"/><text x="${x+12}" y="${y+18}" fill="#1e54c9" font-family="monospace" font-size="10">${s.id}</text><text x="${x+12}" y="${y+37}" fill="#2c3036" font-size="11">${esc(s.title.length>29?s.title.slice(0,28)+'…':s.title)}</text></g>`;}).join('')}</svg>`;
    $('#map-cards').innerHTML=list.map(s=>`<article class="map-card ${s.id===view.screen?'current':''}"><button type="button" data-map-screen="${s.id}">${s.id} · ${s.title} ↗</button><p>${s.description}</p><ul>${s.edges.map(e=>`<li class="${e.kind==='state'?'state':''}">${e.kind==='state'?`↻ ${e.label} · ${e.to}`:`<button type="button" data-map-screen="${e.to}">${e.label} → ${e.to}</button>`}</li>`).join('')}</ul></article>`).join('');
    if(!$('#map-dialog').open)$('#map-dialog').showModal();
  }
  document.addEventListener('click',e=>{
    const close=e.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return;}
    const map=e.target.closest('[data-map-screen]');if(map){$('#map-dialog').close();review(map.dataset.mapScreen);return;}
    const role=e.target.closest('[data-role]');if(role){if(role.dataset.role!==view.role)navigate(role.dataset.role==='admin'?'A01':'U01',{role:role.dataset.role});return;}
    const platform=e.target.closest('[data-platform]');if(platform){view.platform=platform.dataset.platform;$('#device').className='device '+view.platform;$$('[data-platform]').forEach(b=>b.setAttribute('aria-pressed',b===platform));return;}
    const inspect=e.target.closest('[data-review]');if(inspect){if(inspect.dataset.state)return toast('Prueba esta condición usando los controles del sketch.');review(inspect.dataset.review);return;}
    const target=e.target.closest('[data-go]');if(target){navigate(target.dataset.go);return;}
    const act=e.target.closest('[data-action]');if(act)handleAction(act.dataset.action,act);
  });
  document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='modal-confirm'){if(!validate(e.target))return;const reason=String(new FormData(e.target).get('reason')||'').trim();if($('[name=reason]',e.target)&&reason.length<8)return setFormError(e.target,'Describe el motivo con al menos 8 caracteres.');$('#confirm-dialog').close();confirmAction?.(reason);}else submit(e.target);});
  document.addEventListener('change',e=>{if(e.target.id==='audit-filter'){view.auditFilter=e.target.value;render();}});
  $('#hotspots').addEventListener('click',()=>{const on=$('#hotspots').getAttribute('aria-pressed')!=='true';$('#hotspots').setAttribute('aria-pressed',on);document.body.classList.toggle('hotspots',on);});
  $('#open-map').addEventListener('click',openMap);
  $('#map-other-role').addEventListener('click',()=>{navigate(view.role==='usuario'?'A01':'U01');openMap();});
  $('#map-visual').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.mapScreen){e.preventDefault();$('#map-dialog').close();review(e.target.dataset.mapScreen);}});
  $('#go-back').addEventListener('click',()=>{const prev=view.trail.pop();if(prev){view.role=prev.role;view.screen=prev.screen;history.pushState(null,'',`#${view.role}/${view.screen}`);render();}});
  $('#reset-demo').addEventListener('click',()=>confirmation({title:'¿Comenzar de nuevo?',text:'Se restablecerán hábitos, preferencias, catálogo y auditoría de esta demo en este navegador.',danger:true,label:'Restablecer demo',onConfirm:()=>{db=seed();registered=null;sessionPassword='Demo2026!';verifiedRecovery=false;view.selected='h1';view.editId=null;view.recommendation=null;view.filter='Todos';view.auditFilter='Todas';view.trail=[];save();view.role='usuario';view.screen='U01';history.replaceState(null,'','#usuario/U01');render();toast('Demo restablecida.');}}));
  window.addEventListener('popstate',()=>{routeFromHash();render();});
  window.addEventListener('hashchange',()=>{routeFromHash();render();});
  routeFromHash();render();
})();
